CREATE TABLE users(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,full_name VARCHAR(160) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE user_roles(user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE seeker_profiles(user_id BIGINT PRIMARY KEY,headline VARCHAR(160),summary TEXT,skills TEXT,location VARCHAR(160),resume_file_name VARCHAR(255),resume_path VARCHAR(500),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE companies(id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_user_id BIGINT NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,website VARCHAR(255),location VARCHAR(160),logo_url VARCHAR(500),verified BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(owner_user_id) REFERENCES users(id));
CREATE TABLE jobs(id BIGINT AUTO_INCREMENT PRIMARY KEY,company_id BIGINT NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,location VARCHAR(160),job_type VARCHAR(30) NOT NULL,category VARCHAR(120),salary_min DECIMAL(12,2),salary_max DECIMAL(12,2),experience_level VARCHAR(60),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',deadline DATE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE INDEX idx_jobs_search ON jobs(title,location,job_type,category,status,created_at);
CREATE TABLE applications(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_id BIGINT NOT NULL,seeker_id BIGINT NOT NULL,cover_letter TEXT,resume_path VARCHAR(500),status VARCHAR(30) NOT NULL DEFAULT 'SUBMITTED',applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_application UNIQUE(job_id,seeker_id),FOREIGN KEY(job_id) REFERENCES jobs(id),FOREIGN KEY(seeker_id) REFERENCES users(id));
CREATE TABLE saved_jobs(user_id BIGINT NOT NULL,job_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,job_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE application_status_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,application_id BIGINT NOT NULL,changed_by BIGINT NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(id),FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE admin_audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT NOT NULL,action VARCHAR(120) NOT NULL,target_type VARCHAR(80) NOT NULL,target_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES users(id));
